    public List<StockAdjustment> handle( FindAllStockAdjustmentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindStockAdjustment,
 * but only if the id matches
 *
 * @param		entity	StockAdjustment
 */
	protected void emitFindStockAdjustment( StockAdjustment entity ) {
		LOGGER.info("handling emitFindStockAdjustment" );
		
	    queryUpdateEmitter.emit(FindStockAdjustmentQuery.class,
	                            query -> query.getFilter().getStockAdjustmentId().equals(entity.getStockAdjustmentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllStockAdjustment
	 * 
	 * @param		entity	StockAdjustment
	 */
	protected void emitFindAllStockAdjustment( StockAdjustment entity ) {
		LOGGER.info("handling emitFindAllStockAdjustment" );
		
	    queryUpdateEmitter.emit(FindAllStockAdjustmentQuery.class,
	                            query -> true,
	                            entity);
	}

